// Validate input and determine source type
const input = $input.first().json;

const sourceType = input.source_type || 'manual';
const region = input.region || 'Sao Paulo';
const csvData = input.csv_data || null;

// Validate required fields
if (sourceType === 'csv' && !csvData) {
  throw new Error('csv_data required when source_type is csv');
}

return [{
  json: {
    source_type: sourceType,
    region: region,
    csv_data: csvData,
    started_at: new Date().toISOString()
  }
}];

// Google Maps scraping via HTTP request
// Searches for 'escritorio de advocacia em [region]'
const region = $input.first().json.region;

// NOTE: Replace with actual Google Maps Places API or scraping approach
// This is a template - actual implementation depends on:
// Option A: Google Places API (requires API key, $0.032/request)
// Option B: SerpAPI Google Maps ($50/mo, 5000 searches)
// Option C: Browser MCP scraping (free but slower)

const searchQuery = `escritorio de advocacia em ${region}`;

return [{
  json: {
    search_query: searchQuery,
    region: region,
    source: 'google_maps',
    note: 'CONFIGURE: Replace with actual Google Maps API call or SerpAPI integration'
  }
}];

// OAB Directory scraping
// Targets: OAB-SP, OAB-RJ, OAB-MG
const region = $input.first().json.region;

// NOTE: Replace with actual OAB scraping
// OAB sites are state-level: www.oabsp.org.br, www.oabrj.org.br, etc.
// Use Browser MCP or HTTP requests to scrape firm listings

return [{
  json: {
    source: 'oab_directory',
    region: region,
    note: 'CONFIGURE: Replace with actual OAB directory scraping'
  }
}];

// CSV import - parse uploaded CSV data
const csvData = $input.first().json.csv_data;

if (!csvData || !Array.isArray(csvData)) {
  throw new Error('csv_data must be an array of lead objects');
}

// Map CSV fields to lead schema
const leads = csvData.map(row => ({
  first_name: row.first_name || row.nome || '',
  last_name: row.last_name || row.sobrenome || '',
  email: row.email || '',
  phone: row.phone || row.telefone || '',
  company_name: row.company_name || row.empresa || row.escritorio || '',
  company_website: row.website || row.site || '',
  role: row.role || row.cargo || '',
  industry: row.industry || 'juridico',
  source: 'csv_import',
  linkedin_url: row.linkedin || '',
  notes: row.notes || row.observacoes || ''
})).filter(lead => lead.first_name && (lead.email || lead.phone || lead.company_name));

return leads.map(lead => ({ json: lead }));

// Deduplication logic
// Match by normalized company_name + city
const leads = $input.all().map(item => item.json);

const normalize = (str) => (str || '').toLowerCase().trim()
  .replace(/escritorio de advocacia /g, '')
  .replace(/advogados associados/g, '')
  .replace(/\s+/g, ' ');

const seen = new Map();
const deduped = [];
let duplicatesRemoved = 0;

for (const lead of leads) {
  const key = normalize(lead.company_name);

  if (seen.has(key)) {
    // Merge: prefer record with more filled fields
    const existing = seen.get(key);
    const existingFields = Object.values(existing).filter(v => v).length;
    const newFields = Object.values(lead).filter(v => v).length;

    if (newFields > existingFields) {
      // New record has more data - replace
      const idx = deduped.findIndex(l => normalize(l.company_name) === key);
      if (idx >= 0) deduped[idx] = { ...existing, ...lead };
    } else {
      // Merge new data into existing
      const idx = deduped.findIndex(l => normalize(l.company_name) === key);
      if (idx >= 0) {
        for (const [k, v] of Object.entries(lead)) {
          if (v && !deduped[idx][k]) deduped[idx][k] = v;
        }
      }
    }
    duplicatesRemoved++;
  } else {
    seen.set(key, lead);
    deduped.push(lead);
  }
}

// Add metadata
const results = deduped.map(lead => ({
  json: {
    ...lead,
    _dedup_key: normalize(lead.company_name),
    _is_complete: !!(lead.company_name && (lead.email || lead.phone || lead.company_website))
  }
}));

// Log summary
console.log(`Dedup: ${leads.length} input -> ${deduped.length} unique (${duplicatesRemoved} removed)`);

return results;

// Validate lead data and set status
const lead = $input.first().json;

const isComplete = lead.company_name && 
  (lead.email || lead.phone || lead.company_website);

return [{
  json: {
    first_name: lead.first_name || 'Unknown',
    last_name: lead.last_name || null,
    email: lead.email || null,
    email_validated: false,
    phone: lead.phone || null,
    whatsapp: lead.whatsapp || null,
    linkedin_url: lead.linkedin_url || null,
    instagram_handle: lead.instagram_handle || null,
    company_name: lead.company_name || null,
    company_website: lead.company_website || null,
    company_size: lead.company_size || null,
    industry: lead.industry || 'juridico',
    role: lead.role || null,
    source: lead.source || 'manual',
    status: isComplete ? 'new' : 'incomplete',
    notes: lead.notes || null,
    tags: lead.tags || [],
    custom_fields: {
      scraped_at: new Date().toISOString(),
      original_source: lead.source,
      ...(lead.custom_fields || {})
    }
  }
}];

// Generate ingestion summary
const items = $input.all();
const summary = {
  total_processed: items.length,
  successful: items.filter(i => !i.json.error).length,
  failed: items.filter(i => i.json.error).length,
  completed_at: new Date().toISOString()
};

console.log('Lead Ingestion Summary:', JSON.stringify(summary));

return [{ json: summary }];
